function validate([y]) {
  if (!Array.isArray(y) || y.length < 2 || y.length > 100000) return 'y needs 2 to 100000 heights.';
  if (y.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each height is a whole number from 1 to 10^9.';
  for (let i = 0; i + 1 < y.length; i++) if (y[i] === y[i + 1]) return 'Neighbouring heights must differ.';
  return null;
}

