function maxIntersectionCount(y) {
  const n = y.length;
  const events = [];
  for (let i = 0; i + 1 < n; i++) {
    const from = 2 * y[i];
    let to = 2 * y[i + 1];
    // The segment's end point belongs to the next segment, unless this is the last one.
    if (i + 2 < n) {
      to += from < to ? -1 : 1;
    }
    events.push([Math.min(from, to), 1]);
    events.push([Math.max(from, to) + 1, -1]);
  }
  // At equal heights, closing events come before opening ones.
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  let current = 0;
  let best = 0;
  for (const [, change] of events) {
    current += change;
    best = Math.max(best, current);
  }
  return best;
}

