function maxIntersectionCount(y) {
  const heights = [];
  for (const v of y) heights.push(2 * v - 1, 2 * v, 2 * v + 1);
  let best = 0;
  for (const h of heights) {
    let count = 0;
    for (let i = 0; i < y.length; i++) {
      if (2 * y[i] === h) count++;
      if (i + 1 < y.length) {
        const low = 2 * Math.min(y[i], y[i + 1]);
        const high = 2 * Math.max(y[i], y[i + 1]);
        if (low < h && h < high) count++;
      }
    }
    best = Math.max(best, count);
  }
  return best;
}

