function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 9);
  const top = size === 'large' ? (rand() < 0.5 ? 1000000000 : 3 + Math.floor(rand() * 60)) : 2 + Math.floor(rand() * 6);
  const y = [1 + Math.floor(rand() * top)];
  while (y.length < n) {
    let next = 1 + Math.floor(rand() * top);
    if (next === y[y.length - 1]) next = next === top ? 1 : next + 1;
    y.push(next);
  }
  return [y];
}
